1	import { copyFileSync, mkdirSync, rmSync, renameSync, readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
2	import { join, dirname } from 'node:path';
3	import { fileURLToPath, pathToFileURL } from 'node:url';
4	import { computeVendorSet, SHARED_SUBDIR } from '../../../vendoring/compute-vendor-set.mjs';
5	import { loadPacks, resolveDeclaredPacks, packEntryId } from '../../../engine/pack_loader/pack-registry.mjs';
6	import { ENGINE_VERSION } from '../../../engine/version.mjs';
7	import { isVersion, versionAbove } from '../../../engine/version.mjs';
8	import { RENAMED_PACKS } from '../../../engine/pack_loader/renamed-packs.mjs';
9	import { migrationDirs, migrationApplies, flowOf, DECLARATION_FILE } from '../../../engine/checks/helpers/active-migrations.mjs';
10	import { settingsPath } from '../../../engine/settings-file.mjs';
11	import { installedVersions, hasInstalledMount, withInstalledVersions } from '../../../engine/installed-versions.mjs';
12	import { loadMigrations, applyMigration, WITHHOLD_CAPABLE_ENV } from '../../../engine/migrations/registry.mjs';
13	import { NEEDS_HUMAN, runSelfTest, deliveryDecision } from './engine-update.mjs';
14	
15	// THE PACK UPDATE FLOW (docs/versioned-updates/DESIGN.md §3): move one repo's
16	// declared packs from the versions it has installed to the ones this canon ships.
17	// The same shape as the engine flow beside it — vendor, migrate, converge, stamp,
18	// gate — with three deliberate differences, each a consequence of what a pack IS:
19	//
20	//   1. IT PUSHES NO WORKFLOW FILE, because it cannot: GitHub refuses the Action's
21	//      GITHUB_TOKEN under `.github/workflows/` and rejects the WHOLE ref for trying, so
22	//      one such path in the pushed tree fails the entire update. What it does instead is
23	//      the WITHHOLD lane — the write is staged to `.claudinite/pending-workflows/` and
24	//      reported in `withheld`, which raises the apply stage, whose session holds a
25	//      credential that may write there (#1509). The lane was retired in #1317 on the
26	//      premise that a member's workflows are static after adoption; #1494's executor
27	//      line is the counterexample that re-opened it.
28	//   2. IT ENFORCES `minEngineVersion`. A pack version declares the lowest engine it
29	//      runs on; applying it past that is a guess, and a guess about whether a
30	//      member's engine can load a pack is how a fleet goes quiet. Violation is a
31	//      terminal, never a downgrade to "try anyway".
32	//   3. IT HAS AN AGENTIC TAIL — the one place agentic work survives, because the
33	//      pack's new rules meet member-authored content the canon has never seen. This
34	//      module is the DETERMINISTIC half and ends by saying whether that stage is
35	//      needed; the stage itself belongs to the shell that can dispatch a session.
36	//
37	// Everything else is shared with the engine flow on purpose: the same version
38	// predicate decides the gap, the same self-test gates the merge, and every
39	// non-green end is the same `needs-human` terminal (DESIGN §5).
40	const canonRoot = dirname(dirname(dirname(dirname(fileURLToPath(import.meta.url))))); // <canon>/packs/claudinite-lifecycle/updates/<this file>
41	
42	// A pack's own half of the vendor set: its directory, and nothing else. The engine
43	// tree and the catalog belong to the engine flow, which is what keeps two flows
44	// converging one mount from ever fighting over a file.
45	export const isPackFile = (rel, id) => rel.startsWith(`packs/${id}/`);
46	
47	// The mount directories a pack has been vendored under BEFORE — every spelling that
48	// resolves to this id today (renamed-packs.mjs). A rename moves a pack's canon
49	// directory, and the vendor step below replaces a tree per id: the old directory
50	// matches no id any more, so without this it would sit in the mount forever holding a
51	// complete, loadable copy of the pack. That copy is not inert — `discoverPacks`
52	// canonicalizes a mounted pack's own id, so the stale tree announces the SAME id as
53	// the live one and the member runs the pack twice, one of them frozen at whatever it
54	// was renamed from. Swept here rather than by a migration record so the cleanup is a
55	// property of renaming, not something each rename has to remember.
56	export const legacySpellingsOf = (id) =>
57	  Object.entries(RENAMED_PACKS).filter(([, to]) => to === id).map(([from]) => from);
58	
59	// The records this repo still needs for one pack, oldest first — the same predicate
60	// the engine flow ranges over, with that pack's number instead of the engine's.
61	export function packRecordsInGap(id, installed, { today } = {}) {
62	  return migrationDirs().filter((d) => {
63	    const of = flowOf(d);
64	    return of.flow === 'pack' && of.pack === id && migrationApplies(d, { installed, today });
65	  });
66	}
67	
68	// What a pack update would do to each declared pack, judged before anything is
69	// written: its installed version, the version this canon ships, whether the repo's
70	// engine satisfies the pack's minimum, and the records in between.
71	//
72	// `blocked` is the whole point of returning this rather than a boolean. A pack the
73	// engine is too old for is not skipped quietly and not applied hopefully — it is
74	// named, with both numbers, because the fix (update the engine first) is a sentence
75	// long and unguessable from a silent no-op.
76	export function planPackUpdates(packs, declared, installed, { today, engineVersion = ENGINE_VERSION } = {}) {
77	  const byId = new Map(packs.map((p) => [p.id, p]));
78	  const plan = [];
79	  for (const entry of resolveDeclaredPacks(declared ?? [], packs)) {
80	    const id = packEntryId(entry);
81	    const pack = id === undefined ? undefined : byId.get(id);
82	    if (!pack || plan.some((p) => p.id === id)) continue;      // a local pack, or already planned
83	    const from = installed?.packVersions?.[id];
84	    const to = pack.version;
85	    const needs = pack.minEngineVersion;
86	    const blocked = isVersion(needs) && versionAbove(needs, engineVersion)
87	      ? `pack "${id}" version ${to} needs engine ${needs}; this repo runs engine ${engineVersion}`
88	      : null;
89	    plan.push({
90	      id,
91	      from: isVersion(from) ? from : null,
92	      to: isVersion(to) ? to : null,
93	      blocked,
94	      records: packRecordsInGap(id, installed, { today }),
95	    });
96	  }
97	  return plan;
98	}
99	
100	const outcome = (status, detail, extra = {}) => ({ status, detail, ...extra });
101	
102	// Everything under here is a path this flow's caller cannot push, and the one
103	// definition of that fact. A record naming such a path is withheld from the pushed tree
104	// and staged for the apply stage, which delivers it on a credential that can.
105	export const WORKFLOW_DIR = '.github/workflows/';
106	
107	// Where a withheld workflow file waits between this run staging it and the apply stage
108	// delivering it. Inside `.claudinite/`, so it rides the ordinary push the Action token
109	// CAN make; only the real `.github/workflows/` path is refused.
110	export const PENDING_DIR = '.claudinite/pending-workflows/';
111	
112	// Where a withheld workflow path is staged. One level deep and named for the workflow
113	// file itself, so the apply stage recovers the destination from the staged name alone.
114	export const stagedAt = (workflowPath) => `${PENDING_DIR}${workflowPath.slice(WORKFLOW_DIR.length)}`;
115	
116	// Every staged file, repo-relative. One level deep, which is all `.github/workflows/`
117	// itself has. The sweep in `packUpdate` reads this to clear what an EARLIER cycle left
118	// without touching what the current one just staged.
119	export function stagedFiles(targetRoot) {
120	  const dir = join(targetRoot, PENDING_DIR);
121	  if (!existsSync(dir)) return [];
122	  return readdirSync(dir, { withFileTypes: true }).filter((e) => e.isFile()).map((e) => `${PENDING_DIR}${e.name}`);
123	}
124	
125	// The member's vendored scheduler stub. Read from the MEMBER, not from this canon
126	// clone: the engine flow refreshed it earlier in the same cycle, and reading the
127	// member's copy is what makes this agree with `converge-wiring.mjs`'s own CLI —
128	// the thing a human runs by hand, and the thing bootstrap runs at adoption.
129	// Where the tasks pack's scheduler stub sits in a member's mount. EMPTIED of its
130	// caller, not removed, for the reason every `updates/*` export is — the tasks pack's
131	// own converge-workflows.mjs resolves the stubs it scaffolds from.
132	const STUB_DIR = '.claudinite/shared/packs/claudinite-tasks/stubs/';
133	export const stubFor = () => `${STUB_DIR}claudinite-scheduler.yml`;
134	
135	// The scheduler and executor workflows a member should be carrying. EMPTIED, NOT
136	// REMOVED, for the reason every `updates/*` export is. No flow computes a workflow's
137	// content any more: the files are static after adoption and the tasks pack scaffolds
138	// them there (converge-workflows.mjs). `pending: null` is what "nothing to deliver"
139	// has always meant to a caller, so a stale worker still reads a coherent answer.
140	export async function pendingSchedulerWorkflow() { return { pending: null, error: null }; }
141	export async function pendingExecutorWorkflow() { return { pending: null, error: null }; }
142	
143	export function applyStageFor(specs, withheld = []) {
144	  const asked = specs.filter((m) => m.applyStage);
145	  if (!asked.length && !withheld.length) return { needed: false };
146	  // A withheld workflow file needs the stage on its own, with no record asking: the file
147	  // is staged and undelivered, and only the stage's credential can finish it.
148	  // The reason names the CONDITION and the ARTIFACTS BY IDENTITY, and stops there —
149	  // it becomes `reason.detail` on the work item, and the payload it rides in
150	  // carries identifiers, never instructions (updates/terminals.mjs). So a record that
151	  // asked for a session is named, not quoted: its `applyStage.instructions` are in
152	  // the mount the update just vendored, on the branch the session is given, and the
153	  // session reads them from there like any other fact about the repo.
154	  const why = [
155	    ...(withheld.length ? [`${withheld.length} withheld workflow file(s) staged under ${PENDING_DIR}`] : []),
156	    ...asked.map((m) => `${m.dir}: ${m.applyStage.why}`),
157	  ].join('; ');
158	  return {
159	    needed: true,
160	    // The packs that RAISED the records, not every pack whose version moved: this
161	    // scopes a session, and naming packs with nothing to apply widens it.
162	    packs: [...new Set(asked.map((m) => flowOf(m.dir).pack))],
163	    records: asked.map((m) => m.dir),
164	    withheld,
165	    why,
166	  };
167	}
168	
169	// Update `targetRoot`'s declared packs to the versions this canon ships. Same
170	// arguments and same terminals as the engine flow; `dryRun` judges everything and
171	// writes nothing.
172	export async function packUpdate(targetRoot, {
173	  fullName, today, dryRun = false, delivery = 'auto-merge', forceMergeOnRedCi = false, selfTestRun,
174	  extraRecords = [],
175	} = {}) {
176	  const settingsFile = settingsPath(targetRoot);
177	  if (!existsSync(settingsFile)) {
178	    return outcome(NEEDS_HUMAN, `${targetRoot} has no ${DECLARATION_FILE} — it has never adopted Claudinite`);
179	  }
180	  let raw;
181	  try { raw = JSON.parse(readFileSync(settingsFile, 'utf8')); }
182	  catch (e) { return outcome(NEEDS_HUMAN, `${DECLARATION_FILE} is not valid JSON: ${e.message}`); }
183	
184	  // The shape reader canonicalizes a legacy map's keys on the way out: a pack
185	  // renamed since a member last stamped it reads as never-installed otherwise.
186	  const installed = hasInstalledMount(raw) ? installedVersions(raw) : null;
187	  const declared = Array.isArray(raw.packs) ? raw.packs : [];
188	  const packs = await loadPacks();
189	
190	  // The engine the TARGET runs, not the one this canon ships: a member is updated
191	  // engine-first, and a pack update that read the canon's number would enforce
192	  // `minEngineVersion` against an engine the repo does not have.
193	  const engineVersion = isVersion(installed?.engineVersion) ? installed.engineVersion : ENGINE_VERSION;
194	  const plan = planPackUpdates(packs, declared, installed, { today, engineVersion });
195	
196	  const blocked = plan.filter((p) => p.blocked);
197	  if (blocked.length) {
198	    return outcome(NEEDS_HUMAN, blocked.map((p) => p.blocked).join('; '), { plan });
199	  }
200	
201	  const { files, errors } = await computeVendorSet(declared, { today, installed });
202	  if (errors.length) return outcome(NEEDS_HUMAN, errors.map((e) => e.what).join('; '), { errors, plan });
203	
204	  const ids = plan.map((p) => p.id);
205	  const packFiles = files.filter((f) => ids.some((id) => isPackFile(f, id)));
206	  if (dryRun) {
207	    return outcome('ok', `would update ${plan.length} pack(s)`, { plan, files: packFiles.length, dryRun: true });
208	  }
209	
210	  // 1. Replace each declared pack's tree wholesale — per pack, so a pack that is no
211	  //    longer declared keeps its files until the flow that owns removal takes them,
212	  //    and a pack this run does not touch is never disturbed. A pack the canon has
213	  //    RENAMED takes its old directories with it (legacySpellingsOf above).
214	  const sharedDir = join(targetRoot, SHARED_SUBDIR);
215	  for (const id of ids) {
216	    rmSync(join(sharedDir, 'packs', id), { recursive: true, force: true });
217	    for (const legacy of legacySpellingsOf(id)) rmSync(join(sharedDir, 'packs', legacy), { recursive: true, force: true });
218	  }
219	  for (const file of packFiles) {
220	    const dest = join(sharedDir, file);
221	    mkdirSync(dirname(dest), { recursive: true });
222	    copyFileSync(join(canonRoot, file), dest);
223	  }
224	
225	  // 2. Run each pack's records, in the order the gap gives them.
226	  const wanted = new Set(plan.flatMap((p) => p.records));
227	  const specs = (await loadMigrations()).filter((m) => wanted.has(m.dir));
228	  const exists = (p) => existsSync(join(targetRoot, p));
229	  const read = (p) => (existsSync(join(targetRoot, p)) ? readFileSync(join(targetRoot, p), 'utf8') : null);
230	
231	  const put = (p, c) => { mkdirSync(dirname(join(targetRoot, p)), { recursive: true }); writeFileSync(join(targetRoot, p), c); };
232	
233	  // A path under `.github/workflows/` is WITHHELD from the pushed tree and staged for the
234	  // apply stage (#649, re-opened in #1509). The flow's caller pushes with the Action's
235	  // GITHUB_TOKEN, which GitHub never lets write there, and the refusal rejects the whole
236	  // ref — so the file must not be in the tree this run commits. The apply stage is a
237	  // different credential: it raises a work item for an agent session, and the Claude
238	  // GitHub App carries `workflows: write`, which is what actually delivers the file.
239	  //
240	  // #1317 dropped these writes instead, on the ground that "a member's workflows are
241	  // static after adoption". #1494 is the counterexample — the executor's CLAUDINITE_VARS
242	  // line is a workflow change every member needs — so the lane is open again.
243	  const withheld = [];
244	  // Which packs finished this run still OWING a file. A withheld path is delivered by
245	  // the apply stage on another credential, not here, so the pack it belongs to has not
246	  // actually reached the version this run would stamp — see the stamp step below.
247	  //
248	  // Attributed as the write happens rather than by counting `withheld` afterwards: two
249	  // records from DIFFERENT packs may name the same workflow path, and the second one's
250	  // write grows nothing, so a count would stamp the pack whose content is the one
251	  // actually staged.
252	  const owesDelivery = new Set();
253	  let owedBy = null;
254	  const write = (p, c) => {
255	    if (!p.startsWith(WORKFLOW_DIR)) return put(p, c);
256	    put(stagedAt(p), c);
257	    if (!withheld.includes(p)) withheld.push(p);
258	    if (owedBy) owesDelivery.add(owedBy);
259	  };
260	  const move = (from, to) => { mkdirSync(dirname(join(targetRoot, to)), { recursive: true }); renameSync(join(targetRoot, from), join(targetRoot, to)); };
261	  const readTemplate = (p) => (existsSync(join(canonRoot, p)) ? readFileSync(join(canonRoot, p), 'utf8') : null);
262	  // The announcement is what un-skips a record naming a workflow path. It is an env
263	  // handshake rather than a probe of the disk because what matters is what THIS process
264	  // can do, and the vendor step earlier in this same cycle already replaced the on-disk
265	  // worker while the old code is still running (registry.mjs states the same).
266	  // The three the task-declaration conversion needs beyond the classic set (the
267	  // registry says why it is inert without them).
268	  const listDir = (p) => { try { return readdirSync(join(targetRoot, p)); } catch { return null; } };
269	  const remove = (p) => rmSync(join(targetRoot, p), { force: true });
270	  const importModule = (p) => import(pathToFileURL(join(targetRoot, p)).href);
271	  const io = { exists, move, read, write, readTemplate, listDir, remove, importModule, env: { [WITHHOLD_CAPABLE_ENV]: '1' } };
272	  const applied = [];
273	  for (const m of [...specs, ...extraRecords]) {
274	    owedBy = flowOf(m.dir).pack ?? null;
275	    applied.push(...(await applyMigration(m, io)));
276	  }
277	  owedBy = null;
278	
279	  // 2c. THE CLAUDE.md PACK INDEX (#807), for the same reason as 2b and at the same
280	  //     point: its content is a function of the pack set, and the vendor above is
281	  //     what just changed it. The engine flow converges the index too, but it runs
282	  //     BEFORE the packs in a cycle — so on the one night a pack lands, the engine
283	  //     flow's copy is already yesterday's, and without this the member would carry
284	  //     a stale index (and inject the whole corpus through the hook as a fallback)
285	  //     until some later cycle happened to touch the engine.
286	  //
287	  //     Written straight to the tree rather than withheld: the index is not a
288	  //     workflow path, so no credential refuses it.
289	  const { writeRulesIndex, RULES_INDEX_FILE } = await import('../../../engine/pack_loader/generate-rules-index.mjs');
290	  const { ensureRulesIndexImport, ensureRulesIndexMergeAttribute } = await import('../../../engine/converge-wiring.mjs');
291	  if (await writeRulesIndex(targetRoot)) applied.push(`converged ${RULES_INDEX_FILE}`);
292	  if (ensureRulesIndexImport(targetRoot)) applied.push('added the CLAUDE.md pack-index import');
293	  if (ensureRulesIndexMergeAttribute(targetRoot)) applied.push('declared merge=ours for the pack index');
294	
295	  // …and sweep the staging directory of anything this run did NOT put there: a file
296	  // staged by an earlier cycle was either delivered or abandoned, and either way the
297	  // record that staged it would stage it again. Scoping the sweep is load-bearing — an
298	  // unscoped one deletes the delivery this very run just staged, silently and green.
299	  const stagedNow = new Set(withheld.map(stagedAt));
300	  for (const stale of stagedFiles(targetRoot)) {
301	    if (stagedNow.has(stale)) continue; // this run's own delivery, not a leftover
302	    rmSync(join(targetRoot, stale), { force: true });
303	  }
304	
305	  // 3. Stamp each updated pack's version. Written per pack rather than wholesale, so
306	  //    a pack this run did not touch keeps the number it really has.
307	  const next = JSON.parse(readFileSync(settingsFile, 'utf8'));
308	  // Only what this run moved: a version lands on the entry of the pack it prices,
309	  // and a pack this run did not touch keeps the number it really has. The old
310	  // spelling of a renamed pack cannot be carried forward here even by accident —
311	  // there is no map to carry it in, only entries the declaration itself names
312	  // (#1041 is what a second key in a central map cost).
313	  //
314	  //    A PACK THAT STILL OWES A WITHHELD FILE IS NOT STAMPED (#1545). The stamp is
315	  //    this member's claim to have received the version, and a version whose record
316	  //    staged a workflow file has been received only once the apply stage delivers it.
317	  //    Stamping first is unrecoverable rather than merely early: `migrationApplies` is
318	  //    `want > have`, so the moment the stamp lands the record stops applying, stops
319	  //    vendoring, and the staged copy — the one remaining source of the content — is
320	  //    swept by the next cycle as a leftover. Holding the number back keeps the record
321	  //    in range, so an undelivered file is simply staged again next cycle, which is
322	  //    what makes a merged-but-undelivered PR self-healing instead of a silent loss.
323	  const packVersions = {};
324	  for (const p of plan) if (p.to !== null && !owesDelivery.has(p.id)) packVersions[p.id] = p.to;
325	  writeFileSync(settingsFile, `${JSON.stringify(withInstalledVersions(next, { packVersions }), null, 2)}\n`);
326	
327	  // 4. The same gate the engine flow uses, then the agentic tail's own question —
328	  //    ASKED OF THE RECORDS, NOT OF THE VERSION PLAN (#798).
329	  //
330	  //    This used to be `moved.length > 0`: any declared pack whose version number
331	  //    changed summoned a session. That is a fact about the CANON, and the stage
332	  //    exists for a fact about the MEMBER — the pack's new rules met content the
333	  //    canon has never seen. The two coincide only by accident.
334	  //
335	  //    The cost of conflating them was not theoretical. A record can only reach an
336	  //    up-to-date member if its pack's manifest version bumps (`migrationApplies` is
337	  //    `want > have` against the stamped number, and the stamp written is the
338	  //    manifest's). So every mechanical migration — a regex rewrite, a rename, a
339	  //    declaration seed, all deterministic and idempotent — had to buy a session on
340	  //    every member in the fleet to reach them at all. Deterministic work priced as
341	  //    agentic work is how a fleet learns to dread its own updates.
342	  //
343	  //    So the records answer. Each one's author knew which kind they were writing,
344	  //    and `applyStage` is where they say so. A bump carrying no such record is
345	  //    silent, which is what makes a first live run of an agentic change something
346	  //    you can aim at one member instead of fourteen at once.
347	  const selftest = runSelfTest(targetRoot, selfTestRun);
348	  const decision = deliveryDecision({ selftestOk: selftest.ok, delivery, forceMergeOnRedCi });
349	  // A wiring failure rides out on `detail`, which the worker already prints and which
350	  // becomes the PR body and the work item's reason. Appended rather than given a
351	  // field of its own, because a new field only reaches a member when its worker
352	  // catches up a cycle later, and `detail` reaches every fielded worker today.
353	  // No flow computes a workflow any more, so there is no wiring failure left to ride
354	  // out on `detail`. The field stays null rather than absent: a fielded worker reads it,
355	  // and a key that vanished would read as a worker too old to report one.
356	  const wiringError = null;
357	  const detail = decision.why;
358	
359	  return outcome(decision.action === 'needs-human' ? NEEDS_HUMAN : 'ok', detail, {
360	    plan, files: packFiles.length, applied, selftest, decision, withheld,
361	    wiringError, applyStage: applyStageFor(specs, withheld),
362	  });
363	}
