1	import { existsSync } from 'node:fs';
2	import { join } from 'node:path';
3	import { finding } from '../../engine/checks/helpers/findings.mjs';
4	import { LOCAL_PACKS_SUBDIR } from '../../engine/pack_loader/pack-registry.mjs';
5	import {
6	  normalizeEdges, barrierFindings, staleFindings, specFinding,
7	} from '../../engine/checks/helpers/reference-scanning.mjs';
8	
9	// The default doc pointer for barrier rules is this PACK's policy — the engine
10	// helper points at no pack content.
11	export const DEFAULT_DOC = 'packs/basics/barriers.md';
12	
13	// Pack-contributed barriers — how another pack ships a FIXED barrier without
14	// importing this pack's code (pack-independence). The contributing pack
15	// declares `requires: ['barriers']` and carries the barrier as DATA on its
16	// manifest:
17	//
18	//   contributes: { barriers: [{ id, edges, description?, why?, doc?,
19	//                               severity?, crossingRemedy?, crossingExcuse?,
20	//                               gateDir? }] }
21	//
22	// The runner's generic seam hands this pack the ACTIVE pack list
23	// (`contributedRules` on pack.mjs); this factory builds a first-class rule per
24	// contribution — the contribution's own id, so per-rule overrides
25	// (`rules: { "<id>": "off" }`) and acceptances keep addressing it exactly as
26	// they addressed the formerly code-composed rule. `gateDir` is the one
27	// declarative gate a contribution may carry: the rule stays inert until that
28	// directory exists in the repo under test (the vendored-mount gate the
29	// baseline's isolation barrier rides).
30	function contributedRule({ id, edges, severity = 'blocking', doc = DEFAULT_DOC, description, why, crossingRemedy, crossingExcuse, gateDir }) {
31	  const norm = normalizeEdges(edges);
32	  const rule = {
33	    id,
34	    severity,
35	    doc,
36	    description: description || 'Files under a guarded folder must not reference a barred folder',
37	    why: why || 'a folder barrier encodes an architectural boundary; a crossing reference erodes it silently',
38	    // Both halves of a crossing finding's `fix` are overridable here (see
39	    // barrierFindings): `crossingRemedy` replaces the default "route it
40	    // through a shared folder" opener where that is not the way out, and
41	    // pack-shipped edges can't take project-side except entries, so a fixed
42	    // barrier names its real excusal lever too.
43	    crossingRemedy,
44	    crossingExcuse,
45	    run(ctx) {
46	      if (gateDir && !existsSync(join(ctx.root, gateDir))) return [];
47	      const out = norm.errors.map((e) => specFinding(rule, e));
48	      const { findings, stale } = barrierFindings(ctx, norm.edges, rule);
49	      out.push(...findings);
50	      const scanErrors = findings.some((f) => f.resolved === undefined);
51	      if (ctx.mode === 'all' && !norm.errors.length && !scanErrors) out.push(...staleFindings(stale, rule));
52	      return out;
53	    },
54	  };
55	  return rule;
56	}
57	
58	// A malformed contribution must fail loudly at the contributing manifest, not
59	// silently enforce nothing (the same posture as a malformed barriers config).
60	function faultRule(file, what) {
61	  const rule = {
62	    id: 'barrier',
63	    severity: 'blocking',
64	    doc: DEFAULT_DOC,
65	    description: 'A contributed barrier must be well-formed',
66	    why: 'a malformed barrier contribution silently enforces nothing',
67	  };
