1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { mkdtempSync, mkdirSync, writeFileSync, copyFileSync, readFileSync } from 'node:fs';
4	import { tmpdir } from 'node:os';
5	import { join, dirname } from 'node:path';
6	import { fileURLToPath, pathToFileURL } from 'node:url';
7	import { execFileSync } from 'node:child_process';
8	
9	// This test lives at <repo>/vendoring/compute-vendor-set.test.mjs.
10	const MOUNT_DIR = dirname(fileURLToPath(import.meta.url)); // <canon>/vendoring/
11	const REPO_ROOT = dirname(MOUNT_DIR);
12	
13	function writeAt(root, rel, content) {
14	  mkdirSync(dirname(join(root, rel)), { recursive: true });
15	  writeFileSync(join(root, rel), content);
16	}
17	
18	// A hermetic canon mirroring the real layout: the REAL vendor.mjs with the
19	// REAL modules it imports (engine/pack_loader/pack-registry.mjs, engine/checks/helpers/module-imports.mjs — all
20	// self-locate relative to their own file), a small engine tree with the things
21	// that must be EXCLUDED present (tests, engine-root docs, an undeclared top-level
22	// tree), and
23	// fixture packs/skills — so the tests exercise the structural-discovery
24	// contract, not the live corpus's contents.
25	function makeCanon({ packs = [], skills = [], packDirectory = true } = {}) {
26	  const root = mkdtempSync(join(tmpdir(), 'claudinite-vendor-'));
27	  mkdirSync(join(root, 'vendoring'), { recursive: true });
28	  mkdirSync(join(root, 'engine', 'pack_loader'), { recursive: true });
29	  mkdirSync(join(root, 'engine', 'checks', 'helpers'), { recursive: true });
30	  mkdirSync(join(root, 'packs'), { recursive: true });
31	  copyFileSync(join(MOUNT_DIR, 'compute-vendor-set.mjs'), join(root, 'vendoring', 'compute-vendor-set.mjs'));
32	  copyFileSync(join(REPO_ROOT, 'engine', 'pack_loader', 'pack-registry.mjs'), join(root, 'engine', 'pack_loader', 'pack-registry.mjs'));
33	  // The registry validates every manifest against the spec, so the fake corpus
34	  // needs the spec module too — it is part of the loader, not an optional extra.
35	  copyFileSync(join(REPO_ROOT, 'engine', 'pack_loader', 'pack-schema.mjs'), join(root, 'engine', 'pack_loader', 'pack-schema.mjs'));
36	  copyFileSync(join(REPO_ROOT, 'engine', 'pack_loader', 'pack-conventions.mjs'), join(root, 'engine', 'pack_loader', 'pack-conventions.mjs'));
37	  copyFileSync(join(REPO_ROOT, 'engine', 'pack_loader', 'renamed-packs.mjs'), join(root, 'engine', 'pack_loader', 'renamed-packs.mjs'));
38	  copyFileSync(join(REPO_ROOT, 'engine', 'checks', 'helpers', 'module-imports.mjs'), join(root, 'engine', 'checks', 'helpers', 'module-imports.mjs'));
39	  // The recency predicate the migrations walk shares with check-tolerance.
40	  copyFileSync(join(REPO_ROOT, 'engine', 'checks', 'helpers', 'active-migrations.mjs'), join(root, 'engine', 'checks', 'helpers', 'active-migrations.mjs'));
41	  // The engine version the set reports beside the files — the real module, so the
42	  // fixture cannot disagree with the canon about what version this engine is.
43	  copyFileSync(join(REPO_ROOT, 'engine', 'version.mjs'), join(root, 'engine', 'version.mjs'));
44	  // Where a member's settings live and what shape the versions in them take — real
45	  // modules, because the import closure walks them out of active-migrations.
46	  for (const f of ['settings-file.mjs', 'settings-file-names.mjs']) copyFileSync(join(REPO_ROOT, 'engine', f), join(root, 'engine', f));
47	  copyFileSync(join(REPO_ROOT, 'engine', 'installed-versions.mjs'), join(root, 'engine', 'installed-versions.mjs'));
48	  // engine roots: real-shaped content plus everything that must stay out
49	  writeAt(root, 'engine/checks/check_the_world.mjs', 'stub\n');
50	  writeAt(root, 'engine/checks/helpers/repo-context.mjs', 'stub\n');
51	  // The pattern-check engine the registry reaches for when a pack carries
52	  // declared-checks.json — a stub here: the fixture packs declare none, but the
53	  // set's import-closure guard still resolves the registry's reference to it.
54	  writeAt(root, 'engine/checks/helpers/pattern-rules.mjs', 'stub\n');
55	  writeAt(root, 'engine/checks/README.md', 'canon doc\n');
56	  // engine .md is maintainer reference and never vendors — the operational documents a
57	  // consumer reads at runtime are a pack's, and ride the pack walk (#1317).
58	  // (kept: the old whitelist's fixture, now asserting the blanket drop)
59	  // despite .md) beside a maintainer doc (excluded like every other engine .md).
60	  writeAt(root, 'engine/scheduler/DESIGN.md', 'canon doc\n');
61	  writeAt(root, 'engine/test/runner.test.mjs', 'stub\n');
62	  writeAt(root, 'engine/hooks/session-start-command.sh', 'stub\n');
63	  writeAt(root, 'vendoring/DESIGN.md', 'canon doc\n');
64	  // machinery roots: top-level .mjs picked up, tests and dirs' docs not
65	  writeAt(root, 'engine/pack_loader/generate-rules-index.mjs', 'stub\n');
66	  writeAt(root, 'engine/pack_loader/env-requirements.mjs', 'stub\n');
67	  writeAt(root, 'packs/env.test.mjs', 'stub\n');
68	  writeAt(root, 'packs/README.md', 'canon doc\n');
69	  writeAt(root, 'engine/pack_loader/mount-skills.mjs', 'stub\n');
70	  // the full pack directory: generated catalog, vendored unconditionally
71	  if (packDirectory) writeAt(root, 'packs/directory.GENERATED.md', 'stub catalog\n');
72	  // a top-level tree no engine root and no pack names: the set is what the
73	  // declaration reaches, never "everything that happens to be in the canon"
74	  writeAt(root, 'canon-only/notes.md', 'canon-side\n');
75	  // migrations: the applier + registry + the RECENT record folders vendor
76	  // (task-code-work §7); aged records, the README and tests do not. Records sit
77	  // under the flow that owns them — the engine's own here, and a pack's below —
78	  // so both walks are exercised. Stubs: structural inclusion, recency by
79	  // folder-name date prefix.
80	  writeAt(root, 'engine/migrations/apply.mjs', 'export const apply = 1;\n');
81	  writeAt(root, 'engine/migrations/registry.mjs', 'export const registry = 1;\n');
82	  writeAt(root, 'engine/migrations/2026-01-01-seed/migration.mjs', 'export default {\n  id: "seed",\n  version: 2,\n};\n');
83	  writeAt(root, 'engine/migrations/2026-01-01-seed/note.test.mjs', 'stub\n'); // a test — excluded
84	  writeAt(root, 'engine/migrations/2025-06-01-ancient/migration.mjs', 'export default {\n  id: "ancient",\n  version: 1,\n};\n'); // aged out — excluded
85	  writeAt(root, 'engine/migrations/README.md', 'canon doc\n'); // doc — excluded
86	  for (const { id, requires = [], skills: skl = [], extraFiles = [], version } of packs) {
87	    const declaredVersion = version === undefined ? '' : `, version: ${JSON.stringify(version)}`;
88	    writeAt(root, `packs/${id}/pack.mjs`,
89	      `export default { id: ${JSON.stringify(id)}, requires: ${JSON.stringify(requires)}${declaredVersion} };\n`);
90	    // A pack's skills are bundled in its own tree — the one shape (#385).
91	    for (const name of skl) writeAt(root, `packs/${id}/skills/${name}/SKILL.md`, 'stub\n');
92	    for (const file of extraFiles) {
93	      const [name, content] = typeof file === 'string' ? [file, `stub ${file}\n`] : [file.file, file.content];
94	      writeAt(root, `packs/${id}/${name}`, content);
95	    }
96	  }
97	  return root;
98	}
